class MethodEnum(str, Enum):
    """
    The method used for a measurement or observation
    """
    anthropometry = "anthropometry"
    """
    physical measurement of the human body, including height, weight, and other body dimensions
    """
    survey = "survey"
    """
    list of questions given to a participant for data collection purposes - the survey is filled out by the participant independently
    """
    interview = "interview"
    """
    series of questions posed to a participant by an interviewer for data collection purposes
    """
    calculated = "calculated"
    """
    clinical record that results from a calculation rather than being directly measured
    """
    spirometry = "spirometry"
    """
    breathing test used to assess lung function
    """
    body_plesmography = "body_plesmography"
    """
    precise pulmonary function test where the patient sits in a sealed chamber and breathes into a specialized mouthpiece. This method uses Boyle's Law  and is considered a "gold standard"
    """
    gli = "gli"
    """
    a standard reference range and calculator for spirometry and lung function tests published by the Global Lung Function Initiative in 2012
    """
    gli_global = "gli_global"
    """
    a standard reference range and calculator for spirometry and lung function tests published by the Global Lung Function Initiative in 2022. This is an update of the 2012 standard that is more ethnically diverse
    """
    nhanesiii = "nhanesiii"
    """
    standard reference equations for spirometry published in 2005
    """
    jaffe_reaction = "jaffe_reaction"
    """
    colorimetric method for measuring creatinine based on the Jaffe reaction, in which creatinine reacts with picric acid in alkaline solution
    """
    cbc = "cbc"
    """
    complete blood count; a common blood test that measures the cellular components of blood including red cells, white cells, and platelets
    """
    plac_test = "plac_test"
    """
    Lipoprotein-Associated Phospholipase A2 (Lp-PLA2) test; a blood test used to assess cardiovascular and stroke risk
    """
    enzymatic_creatinine_assay = "enzymatic_creatinine_assay"
    """
    enzymatic method for measuring creatinine using creatininase, offering greater specificity than the Jaffe reaction with fewer interferences
    """
    lc_ms_ms = "lc_ms_ms"
    """
    liquid chromatography-tandem mass spectrometry; a reference method for quantifying analytes with high specificity and sensitivity
    """
    immunoturbidometry = "immunoturbidometry"
    """
    photometric method measuring the turbidity caused by antigen-antibody complexes in suspension
    """
    immunonephelometry = "immunonephelometry"
    """
    optical method measuring light scatter from antigen-antibody complexes to quantify proteins such as albumin
    """
    chemiluminescence_immunoassay = "chemiluminescence_immunoassay"
    """
    immunoassay that uses a chemiluminescent label to detect and quantify an analyte via light emission
    """
    elisa = "elisa"
    """
    enzyme-linked immunosorbent assay; a plate-based immunoassay for detecting and quantifying proteins or antibodies
    """
    albumin_dipstick = "albumin_dipstick"
    """
    semi-quantitative colorimetric urine test strip method for detecting albumin
    """
    hplc = "hplc"
    """
    high-performance liquid chromatography; a chromatographic technique used to separate, identify, and quantify analytes in a mixture
    """
    polysomnography = "polysomnography"
    """
    in-laboratory polysomnography; comprehensive multi-channel sleep study recording brain activity, eye movements, muscle activity, and cardiorespiratory signals
    """
    home_sleep_apnea_test = "home_sleep_apnea_test"
    """
    portable, simplified sleep monitoring performed at home to detect obstructive sleep apnea
    """
    bcg_bcp_colorimetric = "bcg_bcp_colorimetric"
    """
    bromocresol green (BCG) or bromocresol purple (BCP) dye-binding colorimetric assay for measuring albumin concentration
    """
    questionnaire = "questionnaire"
    """
    self-report questionnaire or structured interview instrument used to collect behavioral, dietary, or symptom data
    """
    enzymatic_kinetic_assay = "enzymatic_kinetic_assay"
    """
    enzymatic kinetic (rate) assay standardized by the IFCC; measures the rate of an enzymatic reaction to quantify substrate or enzyme concentration
    """
    diazo_colorimetric = "diazo_colorimetric"
    """
    diazo (van den Bergh) colorimetric method for measuring bilirubin fractions in serum or plasma
    """
    urease_gldh = "urease_gldh"
    """
    enzymatic urease/glutamate dehydrogenase (GLDH) coupled assay for measuring blood urea nitrogen (BUN) or urea
    """
    ion_selective_electrode = "ion_selective_electrode"
    """
    potentiometric method using ion-selective electrodes to measure electrolyte concentrations such as sodium, potassium, and chloride
    """
    agatston_scoring = "agatston_scoring"
    """
    Agatston scoring algorithm applied to non-contrast cardiac CT images to quantify coronary artery calcium
    """
    volume_scoring = "volume_scoring"
    """
    volume-based calcium scoring from non-contrast cardiac CT; reports total calcium volume in mm³
    """
    carotid_ultrasound = "carotid_ultrasound"
    """
    B-mode (2-D) carotid ultrasound imaging used to measure intima-media thickness and detect plaques
    """
    duplex_ultrasound = "duplex_ultrasound"
    """
    duplex ultrasound combining B-mode imaging with Doppler velocity measurements to grade arterial stenosis
    """
    ct_angiography = "ct_angiography"
    """
    computed tomography angiography; contrast-enhanced CT imaging of blood vessels
    """
    automated_hematology = "automated_hematology"
    """
    automated hematology analysis using impedance, electrical resistance, or light-scatter technologies to count and characterize blood cells
    """
    manual_differential = "manual_differential"
    """
    manual microscopic differential cell count performed by a trained laboratory technician or pathologist on a stained blood smear
    """
    one_stage_clotting = "one_stage_clotting"
    """
    one-stage clotting assay (PT-based for Factor VII or aPTT-based for Factor VIII) measuring coagulation factor activity
    """
    chromogenic_assay = "chromogenic_assay"
    """
    chromogenic substrate assay measuring coagulation factor activity via colorimetric detection of a chromogenic substrate cleavage product
    """
    hexokinase_glucose_oxidase = "hexokinase_glucose_oxidase"
    """
    enzymatic assay using hexokinase or glucose oxidase to measure glucose concentration; the reference method for glucose measurement
    """
    clauss_assay = "clauss_assay"
    """
    Clauss functional clotting assay for fibrinogen; measures the time to clot formation after adding thrombin to diluted plasma
    """
    electrocardiography = "electrocardiography"
